49	/// Check if we're at the start of a block quote (`>`).
50	pub(crate) fn at_quote(p: &mut MarkdownParser) -> bool {
51	    p.lookahead(|p| {
52	        let at_virtual_line_start = p.state().virtual_line_start == Some(p.cur_range().start());
53	        if !p.at_line_start() && !p.at_start_of_input() && !at_virtual_line_start {
54	            return false;
55	        }
56	        let mut indent = p.line_start_leading_indent();
57	        if at_virtual_line_start && indent > 0 {
58	            // Treat virtual line start as column 0.
59	            indent = 0;
60	        }
61	        if indent > MAX_BLOCK_PREFIX_INDENT {
62	            return false;
63	        }
64	        p.skip_line_indent(MAX_BLOCK_PREFIX_INDENT);
65	        p.at(T![>])
66	    })
67	}
