38	/// Maximum number of `#` characters allowed in an ATX heading (CommonMark §4.2).
39	const MAX_HEADER_HASHES: usize = 6;
40	
41	/// Check if we might be at an ATX header.
42	/// We only check if the current token is a HASH - full validation happens in parse_header.
43	pub(crate) fn at_header(p: &mut MarkdownParser) -> bool {
44	    p.lookahead(|p| {
45	        if !p.at_line_start() && !p.at_start_of_input() {
46	            return false;
47	        }
48	        p.skip_line_indent(MAX_BLOCK_PREFIX_INDENT);
49	        p.at(T![#])
50	    })
51	}
52	
53	/// Parse an ATX header.
54	///
55	/// Grammar: MdHeader = indent: MdIndentTokenList before: MdHashList content: MdParagraph? after: MdHashList
56	///
57	/// ATX headers start with 1-6 `#` characters followed by space or end of line.
58	/// More than 6 `#` characters is not a valid header.
59	///
60	/// Trailing hashes are optional and must be at the end of the line.
61	pub(crate) fn parse_header(p: &mut MarkdownParser) -> ParsedSyntax {
62	    if !at_header(p) {
63	        return Absent;
64	    }
65	
66	    // Check hash count BEFORE starting to parse (via lookahead).
67	    // The lexer emits all consecutive `#` chars as a single HASH token,
68	    // so we need to verify the token length doesn't exceed 6 before consuming it.
69	    let hash_count = p.lookahead(|p| {
70	        p.skip_line_indent(MAX_BLOCK_PREFIX_INDENT);
71	        if p.at(T![#]) { p.cur_text().len() } else { 0 }
72	    });
73	
74	    // Validate hash count (must be 1-6)
75	    // Diagnostic for >6 hashes is emitted in parse_any_block before try_parse
76	    if hash_count > MAX_HEADER_HASHES {
77	        // Not a valid header - let it be parsed as paragraph
78	        return Absent;
79	    }
80	
81	    let m = p.start();
82	
83	    p.emit_line_indent(MAX_BLOCK_PREFIX_INDENT);
84	
85	    // Parse opening hashes (MdHashList containing MdHash nodes)
86	    parse_hash_list(p);
87	
88	    // Per CommonMark §4.2: opening hashes must be followed by space, tab, or end of line.
89	    // `#foo` is NOT a valid header; `# foo`, `#\tfoo`, or `#\n` are valid.
90	    // Check if the next token has preceding whitespace or we're at EOL/EOF.
91	    if !p.at_inline_end() {
92	        // There's a token after hashes on the same line - check for whitespace
93	        // In Markdown, whitespace is significant and included in token text,
94	        // so we check if the token starts with a space or tab character.
95	        let text = p.cur_text();
96	        let token_starts_with_whitespace = text.starts_with(' ') || text.starts_with('\t');
97	        if !token_starts_with_whitespace {
98	            // No space/tab after hashes - not a valid header (e.g., "#foo")
99	            m.abandon(p);
100	            return Absent;
101	        }
102	    }
103	
104	    // Parse content (optional paragraph) - content goes until end of line
105	    // The header ends at a single newline (not blank line)
106	    parse_header_content(p);
107	
108	    // Parse trailing hashes (MdHashList)
109	    // Trailing hashes are valid if they're at the end of the line
110	    parse_trailing_hashes(p);
111	
112	    Present(m.complete(p, MD_HEADER))
113	}
