118	/// We determine the heading level from the token's text length.
119	///
120	/// Creates MdHashList containing a single MdHash node that wraps the token.
121	///
122	/// Returns the number of hashes (heading level).
123	fn parse_hash_list(p: &mut MarkdownParser) -> usize {
124	    let m = p.start();
125	    let count = if p.at(T![#]) {
126	        let len = p.cur_text().len();
127	        // Wrap the HASH token in an MdHash node to match grammar
128	        let hash_m = p.start();
129	        p.bump(T![#]);
130	        hash_m.complete(p, MD_HASH);
