223	pub(crate) fn parse_any_block_with_indent_code_policy(
224	    p: &mut MarkdownParser,
225	    allow_indent_code_block: bool,
226	) -> ParsedSyntax {
227	    let start = p.cur_range().start();
228	    // Handle standalone NEWLINE tokens as MdNewline nodes.
229	    // This prevents inter-block NEWLINEs from becoming "newline-only paragraphs".
230	    if p.at(NEWLINE) {
231	        let m = p.start();
232	        p.bump(NEWLINE);
233	        return Present(m.complete(p, MD_NEWLINE));
234	    }
235	    if at_blank_line_start(p) {
236	        // Consume blank-line whitespace as whitespace trivia (structural).
237	        while p.at(MD_TEXTUAL_LITERAL) {
238	            let text = p.cur_text();
239	            if text == " " || text == "\t" {
240	                p.consume_as_whitespace_trivia();
241	            } else {
242	                break;
243	            }
244	        }
245	        if p.at(NEWLINE) {
246	            let m = p.start();
247	            p.bump(NEWLINE);
248	            return Present(m.complete(p, MD_NEWLINE));
249	        }
250	        // Blank line with no trailing newline (e.g., end of file)
251	        return Absent;
252	    }
253	
254	    let parsed = if allow_indent_code_block && at_indent_code_block(p) {
255	        parse_indent_code_block(p)
256	    } else if at_fenced_code_block(p) {
257	        parse_fenced_code_block(p)
258	    } else if line_starts_with_fence(p) {
259	        parse_fenced_code_block_force(p)
260	    } else if at_thematic_break_block(p) {
261	        let break_block = try_parse(p, |p| {
262	            let break_block = parse_thematic_break_block(p);
263	            if break_block.is_absent() {
264	                return Err(());
265	            }
266	            Ok(break_block)
267	        });
268	        if let Ok(parsed) = break_block {
269	            parsed
270	        } else {
271	            parse_paragraph(p)
272	        }
273	    } else if at_header(p) {
274	        // Check for too many hashes BEFORE try_parse (which would lose diagnostics on rewind)
275	        let too_many = check_too_many_hashes(p);
276	        let header_result = try_parse(p, |p| {
277	            let header = parse_header(p);
278	            if header.is_absent() {
279	                return Err(());
280	            }
281	            Ok(header)
282	        });
283	        if let Ok(parsed) = header_result {
284	            parsed
285	        } else {
286	            // Emit diagnostic for too many hashes (outside try_parse to persist)
287	            if let Some((range, count)) = too_many {
