299	            p.set_force_ordered_list_marker(true);
300	            p.force_relex_regular();
301	            true
302	        } else {
303	            false
304	        };
305	        let parsed = parse_order_list_item(p);
306	        if forced {
307	            p.set_force_ordered_list_marker(false);
308	        }
309	        if parsed.is_absent() {
310	            parse_paragraph(p)
311	        } else {
312	            parsed
313	        }
314	    } else if at_html_block(p) {
315	        parse_html_block(p)
316	    } else if at_link_block(p) {
