333	        // This can happen when list item indentation is still active.
334	        if at_bullet_list_item_at_any_indent(p) {
335	            let prev_required = p.state().list_item_required_indent;
336	            let prev_virtual = p.state().virtual_line_start;
337	            p.state_mut().list_item_required_indent = 0;
338	            p.state_mut().virtual_line_start = Some(p.cur_range().start());
339	            let parsed = parse_bullet_list_item(p);
340	            p.state_mut().list_item_required_indent = prev_required;
341	            p.state_mut().virtual_line_start = prev_virtual;
342	            if parsed.is_present() {
343	                parsed
344	            } else {
345	                parse_paragraph(p)
346	            }
347	        } else if at_order_list_item_at_any_indent(p) {
348	            let prev_required = p.state().list_item_required_indent;
349	            let prev_virtual = p.state().virtual_line_start;
350	            p.state_mut().list_item_required_indent = 0;
351	            p.state_mut().virtual_line_start = Some(p.cur_range().start());
352	            let parsed = parse_order_list_item(p);
353	            p.state_mut().list_item_required_indent = prev_required;
354	            p.state_mut().virtual_line_start = prev_virtual;
355	            if parsed.is_present() {
356	                parsed
357	            } else {
358	                parse_paragraph(p)
359	            }
360	        } else {
361	            parse_paragraph(p)
362	        }
363	    } else {
364	        // Default fallback: parse as paragraph
365	        parse_paragraph(p)
366	    };
367	
368	    if start == p.cur_range().start() {
369	        let range = p.cur_range();
